package cybershield.model;

/**
 * SecurityAlert — Represents an automated detection alert generated by
 * the CyberShield Intrusion Detection System (IDS).
 * Demonstrates: Domain modeling of detected threats, source attribution,
 * and correlation with automatically generated incidents.
 */
public class SecurityAlert {

    private int id;
    private String alertType;       // e.g. "BRUTE_FORCE_ATTACK"
    private String sourceIp;        // Originating remote IP address
    private int failedAttempts;     // Number of failed attempts triggering threshold
    private String severity;        // "HIGH", "CRITICAL", etc.
    private String status;          // "OPEN", "INVESTIGATING", "RESOLVED"
    private int incidentId;         // Foreign reference to auto-created incident in SQLite
    private String details;         // Explanatory forensics note
    private String createdAt;       // Formatted timestamp string (yyyy-MM-dd HH:mm:ss)
    private long createdAtEpoch;    // Milliseconds epoch for fast sliding-window and cooldown checks

    public SecurityAlert() {
    }

    public SecurityAlert(int id, String alertType, String sourceIp, int failedAttempts,
                         String severity, String status, int incidentId,
                         String details, String createdAt, long createdAtEpoch) {
        this.id = id;
        this.alertType = alertType;
        this.sourceIp = sourceIp;
        this.failedAttempts = failedAttempts;
        this.severity = severity;
        this.status = status;
        this.incidentId = incidentId;
        this.details = details;
        this.createdAt = createdAt;
        this.createdAtEpoch = createdAtEpoch;
    }

    public SecurityAlert(String alertType, String sourceIp, int failedAttempts,
                         String severity, String status, int incidentId,
                         String details, String createdAt, long createdAtEpoch) {
        this(-1, alertType, sourceIp, failedAttempts, severity, status, incidentId, details, createdAt, createdAtEpoch);
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getAlertType() {
        return alertType;
    }

    public void setAlertType(String alertType) {
        this.alertType = alertType;
    }

    public String getSourceIp() {
        return sourceIp;
    }

    public void setSourceIp(String sourceIp) {
        this.sourceIp = sourceIp;
    }

    public int getFailedAttempts() {
        return failedAttempts;
    }

    public void setFailedAttempts(int failedAttempts) {
        this.failedAttempts = failedAttempts;
    }

    public String getSeverity() {
        return severity;
    }

    public void setSeverity(String severity) {
        this.severity = severity;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public int getIncidentId() {
        return incidentId;
    }

    public void setIncidentId(int incidentId) {
        this.incidentId = incidentId;
    }

    public String getDetails() {
        return details;
    }

    public void setDetails(String details) {
        this.details = details;
    }

    public String getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(String createdAt) {
        this.createdAt = createdAt;
    }

    public long getCreatedAtEpoch() {
        return createdAtEpoch;
    }

    public void setCreatedAtEpoch(long createdAtEpoch) {
        this.createdAtEpoch = createdAtEpoch;
    }

    @Override
    public String toString() {
        return "SecurityAlert{" +
                "id=" + id +
                ", type='" + alertType + '\'' +
                ", sourceIp='" + sourceIp + '\'' +
                ", failedAttempts=" + failedAttempts +
                ", severity='" + severity + '\'' +
                ", status='" + status + '\'' +
                ", incidentId=" + incidentId +
                ", createdAt='" + createdAt + '\'' +
                '}';
    }
}

